def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def generate_initial_population(n_pop):
        x = lb + (ub - lb) * rng.random((n_pop, dim))
        return x

    def evaluate(population):
        f_values = [func(x) for x in population]
        return np.array(f_values), population

    def mutate(parent1, parent2, parent3, sigma_scale):
        diff = parent2 - parent1
        mutant = clip(parent1 + sigma_scale * rng.normal(size=dim) * diff)
        return mutant

    def crossover(mutant, target, cr):
        for i in range(dim):
            if rng.random() < cr:
                mutant[i] = target[i]
        return mutant

    n_pop = 50
    population_size = 20
    sigma_scale = 0.1
    cr_initial = 0.5
    cr_final = 0.2
    decay_rate = 0.99
    max_iter_without_improvement = 10

    x = generate_initial_population(n_pop)
    f_values, _ = evaluate(x)

    for i in range(budget):
        idx_best = np.argmin(f_values)
        best_x = x[idx_best]

        # Adaptive crossover strategy
        cr = cr_final + (cr_initial - cr_final) * (1 - decay_rate ** max_iter_without_improvement)
        if rng.random() < 0.5:
            sigma_scale *= 1.01

        for j in range(n_pop):
            parent1_idx, parent2_idx, parent3_idx = np.random.choice(range(n_pop), size=3, replace=False)
            mutant = mutate(x[parent1_idx], x[parent2_idx], x[parent3_idx], sigma_scale)

            if rng.random() < cr:
                mutant = crossover(mutant, x[j], cr)

            idx = (j + n_pop * i) % n_pop
            x[idx] = mutant

        f_values, x = evaluate(x)

        # Early stopping
        if np.min(f_values) == 0:
            return best_x

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    pop = rng.uniform(lb, ub, (1, dim))
    pop_size = 10 + int(np.sqrt(dim))

    for _ in range(budget):
        fit_pop = [func(clip(pop[i])) for i in range(pop_size)]
        fmin = np.min(fit_pop)

        if fit_pop.count(fmin) > 1:
            indices = np.where(np.array(fit_pop) == fmin)[0]
            pop[indices] = rng.uniform(lb, ub, (len(indices), dim))

        else:
            idx_best = np.argmin(fit_pop)
            x_best = clip(pop[idx_best])

            pop_diff = [rng.uniform(-1, 1) for _ in range(dim)]
            children = pop + pop_size * [np.array(x_best) + np.dot(np.array([pop[i] - x_best for i in range(pop_size)]), np.array(pop_diff))]

            fit_children = [func(clip(child)) for child in children]
            idx_child = np.argmin(fit_children)

            if rng.rand() < 0.1:
                pop[idx_child] = clip(children[idx_child])
            else:
                pop[idx_best] = clip(children[idx_child])

    best_x = np.array(pop[np.argmin([func(clip(x)) for x in pop])])
    return best_x

